"use client";
import * as React from "react";
import { createPortal } from "react-dom";
import { cn } from "@/lib/cn";

interface DialogCtx {
  open: boolean;
  setOpen: (v: boolean) => void;
}
const DialogContext = React.createContext<DialogCtx | null>(null);

export interface DialogProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (v: boolean) => void;
  children: React.ReactNode;
}

export function Dialog({ open, defaultOpen, onOpenChange, children }: DialogProps) {
  const isControlled = open !== undefined;
  const [internal, setInternal] = React.useState(defaultOpen ?? false);
  const value = isControlled ? open! : internal;
  const setOpen = (v: boolean) => {
    if (!isControlled) setInternal(v);
    onOpenChange?.(v);
  };
  return <DialogContext.Provider value={{ open: value, setOpen }}>{children}</DialogContext.Provider>;
}

export function DialogTrigger({ children, asChild }: { children: React.ReactElement; asChild?: boolean }) {
  const ctx = React.useContext(DialogContext);
  if (!ctx) throw new Error("DialogTrigger must be inside <Dialog>");
  if (asChild) {
    return React.cloneElement(children, { onClick: () => ctx.setOpen(true) } as React.HTMLAttributes<HTMLElement>);
  }
  return <button onClick={() => ctx.setOpen(true)}>{children}</button>;
}

export interface DialogContentProps {
  children: React.ReactNode;
  className?: string;
}

export function DialogContent({ children, className }: DialogContentProps) {
  const ctx = React.useContext(DialogContext);
  if (!ctx) throw new Error("DialogContent must be inside <Dialog>");
  const [mounted, setMounted] = React.useState(false);

  React.useEffect(() => setMounted(true), []);

  React.useEffect(() => {
    if (!ctx.open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") ctx.setOpen(false);
    };
    document.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [ctx]);

  if (!mounted || !ctx.open) return null;

  return createPortal(
    <div className="fixed inset-0 z-[90] grid place-items-center p-4 animate-[fadeIn_150ms_ease-out]">
      <button
        aria-label="Close"
        onClick={() => ctx.setOpen(false)}
        className="absolute inset-0 cursor-default"
        style={{ background: "color-mix(in oklab, var(--ds-ink) 50%, transparent)", backdropFilter: "blur(6px)" }}
      />
      <div
        role="dialog"
        aria-modal="true"
        className={cn(
          "relative w-full max-w-md rounded-[var(--ds-radius)] border bg-[var(--ds-paper)] border-[var(--ds-line)]",
          "shadow-[var(--ds-shadow)] animate-[scaleIn_180ms_var(--ds-easing)]",
          className,
        )}
      >
        {children}
      </div>
    </div>,
    document.body,
  );
}

export function DialogHeader({ children, className }: { children: React.ReactNode; className?: string }) {
  return <div className={cn("flex flex-col gap-1 p-5 border-b border-[var(--ds-line)]", className)}>{children}</div>;
}

export function DialogTitle({ children, className }: { children: React.ReactNode; className?: string }) {
  return <h2 className={cn("text-lg font-semibold tracking-[-0.01em]", className)}>{children}</h2>;
}

export function DialogDescription({ children, className }: { children: React.ReactNode; className?: string }) {
  return <p className={cn("text-sm text-[var(--ds-ink-soft)]", className)}>{children}</p>;
}

export function DialogBody({ children, className }: { children: React.ReactNode; className?: string }) {
  return <div className={cn("p-5", className)}>{children}</div>;
}

export function DialogFooter({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <div className={cn("flex items-center justify-end gap-2 p-5 border-t border-[var(--ds-line)]", className)}>
      {children}
    </div>
  );
}

export function DialogClose({ children, asChild }: { children: React.ReactElement; asChild?: boolean }) {
  const ctx = React.useContext(DialogContext);
  if (!ctx) throw new Error("DialogClose must be inside <Dialog>");
  if (asChild) {
    return React.cloneElement(children, { onClick: () => ctx.setOpen(false) } as React.HTMLAttributes<HTMLElement>);
  }
  return <button onClick={() => ctx.setOpen(false)}>{children}</button>;
}

import * as React from "react";
import { cn } from "@/lib/cn";

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  hint?: string;
  error?: string;
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, label, hint, error, leading, trailing, id, ...props }, ref) => {
    const reactId = React.useId();
    const inputId = id ?? reactId;
    return (
      <div className="flex flex-col gap-1.5 w-full">
        {label && (
          <label htmlFor={inputId} className="text-xs uppercase tracking-[0.12em] text-[var(--ds-ink-soft)]">
            {label}
          </label>
        )}
        <div
          className={cn(
            "group flex items-center gap-2 rounded-xl border bg-[var(--ds-paper)] px-3.5",
            "border-[var(--ds-line)] shadow-[inset_0_1px_0_rgba(255,255,255,0.5)]",
            "transition-[border-color,box-shadow] duration-150",
            "focus-within:border-[var(--ds-ink)] focus-within:shadow-[0_0_0_4px_color-mix(in_oklab,var(--ds-accent)_25%,transparent)]",
            error && "border-[var(--ds-accent)] focus-within:border-[var(--ds-accent)]",
          )}
        >
          {leading && <span className="text-[var(--ds-muted)]">{leading}</span>}
          <input
            ref={ref}
            id={inputId}
            className={cn(
              "h-10 w-full bg-transparent text-[var(--ds-ink)] placeholder:text-[var(--ds-muted)]",
              "outline-none text-[0.95rem]",
              className,
            )}
            {...props}
          />
          {trailing && <span className="text-[var(--ds-muted)]">{trailing}</span>}
        </div>
        {(hint || error) && (
          <p className={cn("text-xs", error ? "text-[var(--ds-accent)]" : "text-[var(--ds-muted)]")}>
            {error ?? hint}
          </p>
        )}
      </div>
    );
  },
);
Input.displayName = "Input";

import * as React from "react";
import { cn } from "@/lib/cn";

/**
 * Disenio layout primitives — composable, semantic, theme-aware.
 *
 *   Stack     vertical with consistent gap
 *   Cluster   horizontal wrap with gap, alignment, justification
 *   Switcher  row above threshold, stack below
 *   Sidebar   sidebar + content, stacks responsively
 *   Center    constrain max-width and center
 *   Grid      responsive auto-fit grid
 *   Spacer    grows to fill flex space
 *   Divider   horizontal or vertical hairline
 */

type Gap = "none" | "xs" | "sm" | "md" | "lg" | "xl" | "2xl" | number | string;

const GAP_SCALE: Record<Exclude<Gap, number | string>, string> = {
  none: "0",
  xs: "0.25rem",
  sm: "0.5rem",
  md: "1rem",
  lg: "1.5rem",
  xl: "2.5rem",
  "2xl": "4rem",
};

function resolveGap(g: Gap | undefined): string | undefined {
  if (g === undefined) return undefined;
  if (typeof g === "number") return `${g}px`;
  if (typeof g === "string" && !(g in GAP_SCALE)) return g;
  return GAP_SCALE[g as keyof typeof GAP_SCALE];
}

/* ────────────────────────────  Stack  ──────────────────────────── */
export interface StackProps extends React.HTMLAttributes<HTMLDivElement> {
  as?: keyof React.JSX.IntrinsicElements;
  gap?: Gap;
  align?: "start" | "center" | "end" | "stretch";
}
export const Stack = React.forwardRef<HTMLDivElement, StackProps>(
  ({ as: Tag = "div", gap = "md", align, className, style, ...props }, ref) => {
    const Component = Tag as React.ElementType;
    return (
      <Component
        ref={ref}
        className={cn("flex flex-col", className)}
        style={{ gap: resolveGap(gap), alignItems: align, ...style }}
        {...props}
      />
    );
  },
);
Stack.displayName = "Stack";

/* ────────────────────────────  Cluster  ──────────────────────────── */
export interface ClusterProps extends React.HTMLAttributes<HTMLDivElement> {
  as?: keyof React.JSX.IntrinsicElements;
  gap?: Gap;
  align?: "start" | "center" | "end" | "baseline" | "stretch";
  justify?: "start" | "center" | "end" | "between" | "around" | "evenly";
  wrap?: boolean;
}
const JUSTIFY = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  between: "space-between",
  around: "space-around",
  evenly: "space-evenly",
} as const;
const ALIGN = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  baseline: "baseline",
  stretch: "stretch",
} as const;
export const Cluster = React.forwardRef<HTMLDivElement, ClusterProps>(
  ({ as: Tag = "div", gap = "md", align = "center", justify = "start", wrap = true, className, style, ...props }, ref) => {
    const Component = Tag as React.ElementType;
    return (
      <Component
        ref={ref}
        className={cn("flex", className)}
        style={{
          gap: resolveGap(gap),
          alignItems: ALIGN[align],
          justifyContent: JUSTIFY[justify],
          flexWrap: wrap ? "wrap" : "nowrap",
          ...style,
        }}
        {...props}
      />
    );
  },
);
Cluster.displayName = "Cluster";

/* ────────────────────────────  Switcher  ──────────────────────────── */
export interface SwitcherProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Below this width, items stack. Above, they share a row. */
  threshold?: string;
  gap?: Gap;
  /** Soft cap on items per row. */
  limit?: number;
}
export const Switcher = React.forwardRef<HTMLDivElement, SwitcherProps>(
  ({ threshold = "30rem", gap = "md", limit = 4, className, style, ...props }, ref) => {
    const g = resolveGap(gap) ?? "1rem";
    return (
      <div
        ref={ref}
        className={cn("flex flex-wrap", className)}
        style={
          {
            gap: g,
            ["--ds-switcher-threshold" as string]: threshold,
            ["--ds-switcher-limit" as string]: String(limit),
            ...style,
          } as React.CSSProperties
        }
        {...props}
      >
        {React.Children.map(props.children, (child) => (
          <div
            style={{
              flexBasis: `calc((${threshold} - 100%) * 999)`,
              flexGrow: 1,
            }}
          >
            {child}
          </div>
        ))}
      </div>
    );
  },
);
Switcher.displayName = "Switcher";

/* ────────────────────────────  Sidebar  ──────────────────────────── */
export interface SidebarProps extends React.HTMLAttributes<HTMLDivElement> {
  /** "left" places the first child as the side; "right" the second. */
  side?: "left" | "right";
  sideWidth?: string;
  /** Min width the content column must keep before the layout collapses. */
  contentMin?: string;
  gap?: Gap;
  noStretch?: boolean;
}
export const Sidebar = React.forwardRef<HTMLDivElement, SidebarProps>(
  (
    { side = "left", sideWidth = "var(--ds-sidebar-width, 18rem)", contentMin = "50%", gap = "md", noStretch, className, style, children, ...props },
    ref,
  ) => {
    const items = React.Children.toArray(children);
    if (items.length !== 2) {
      // graceful fallback — render as a stack if not exactly 2 children
      return (
        <Stack ref={ref as React.Ref<HTMLDivElement>} className={className} style={style} gap={gap} {...props}>
          {children}
        </Stack>
      );
    }
    const [first, second] = items;
    const sideEl = side === "left" ? first : second;
    const mainEl = side === "left" ? second : first;
    return (
      <div
        ref={ref}
        className={cn("flex flex-wrap", className)}
        style={{ gap: resolveGap(gap), alignItems: noStretch ? "flex-start" : "stretch", ...style }}
        {...props}
      >
        <div style={{ flexBasis: sideWidth, flexGrow: 1 }}>{sideEl}</div>
        <div style={{ flexBasis: 0, flexGrow: 999, minInlineSize: contentMin }}>{mainEl}</div>
      </div>
    );
  },
);
Sidebar.displayName = "Sidebar";

/* ────────────────────────────  Center  ──────────────────────────── */
export interface CenterProps extends React.HTMLAttributes<HTMLDivElement> {
  as?: keyof React.JSX.IntrinsicElements;
  /** Max-width. Accepts a token ("prose"|"narrow"|"wide") or any CSS length. */
  max?: "narrow" | "prose" | "wide" | string;
  /** Horizontal padding. */
  pad?: Gap;
  /** Center child text horizontally too. */
  text?: boolean;
}
const MAX_PRESETS: Record<"narrow" | "prose" | "wide", string> = {
  narrow: "32rem",
  prose: "65ch",
  wide: "72rem",
};
export const Center = React.forwardRef<HTMLDivElement, CenterProps>(
  ({ as: Tag = "div", max = "prose", pad = "md", text = false, className, style, ...props }, ref) => {
    const Component = Tag as React.ElementType;
    const maxW = (MAX_PRESETS as Record<string, string>)[max as string] ?? max;
    return (
      <Component
        ref={ref}
        className={cn("mx-auto box-content", className)}
        style={{
          maxInlineSize: maxW,
          paddingInline: resolveGap(pad),
          textAlign: text ? "center" : undefined,
          ...style,
        }}
        {...props}
      />
    );
  },
);
Center.displayName = "Center";

/* ────────────────────────────  Grid  ──────────────────────────── */
export interface GridProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Min width for an auto-sized column. */
  min?: string;
  gap?: Gap;
}
export const Grid = React.forwardRef<HTMLDivElement, GridProps>(
  ({ min = "16rem", gap = "md", className, style, ...props }, ref) => (
    <div
      ref={ref}
      className={cn("grid", className)}
      style={{
        gap: resolveGap(gap),
        gridTemplateColumns: `repeat(auto-fit, minmax(min(${min}, 100%), 1fr))`,
        ...style,
      }}
      {...props}
    />
  ),
);
Grid.displayName = "Grid";

/* ────────────────────────────  Spacer  ──────────────────────────── */
export interface SpacerProps extends React.HTMLAttributes<HTMLDivElement> {
  size?: Gap;
}
export const Spacer = React.forwardRef<HTMLDivElement, SpacerProps>(
  ({ size, className, style, ...props }, ref) => (
    <div
      ref={ref}
      aria-hidden
      className={cn(size === undefined && "flex-1", className)}
      style={size !== undefined ? { flexBasis: resolveGap(size), flexShrink: 0, ...style } : style}
      {...props}
    />
  ),
);
Spacer.displayName = "Spacer";

/* ────────────────────────────  Divider  ──────────────────────────── */
export interface DividerProps extends React.HTMLAttributes<HTMLHRElement | HTMLDivElement> {
  orientation?: "horizontal" | "vertical";
  label?: React.ReactNode;
}
export function Divider({ orientation = "horizontal", label, className, style, ...props }: DividerProps) {
  if (label && orientation === "horizontal") {
    return (
      <div
        role="separator"
        className={cn("flex items-center gap-3 text-xs uppercase tracking-[0.18em] text-[var(--ds-muted)] mono", className)}
        style={style}
      >
        <span className="flex-1 h-px bg-[var(--ds-line)]" />
        <span>{label}</span>
        <span className="flex-1 h-px bg-[var(--ds-line)]" />
      </div>
    );
  }
  if (orientation === "vertical") {
    return (
      <div
        role="separator"
        aria-orientation="vertical"
        className={cn("self-stretch w-px bg-[var(--ds-line)]", className)}
        style={style}
        {...(props as React.HTMLAttributes<HTMLDivElement>)}
      />
    );
  }
  return (
    <hr
      className={cn("border-0 h-px bg-[var(--ds-line)]", className)}
      style={style}
      {...(props as React.HTMLAttributes<HTMLHRElement>)}
    />
  );
}

"use client";
import * as React from "react";
import { cn } from "@/lib/cn";

export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface SelectProps {
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (v: string) => void;
  placeholder?: string;
  label?: string;
  disabled?: boolean;
  className?: string;
}

export function Select({
  options,
  value,
  defaultValue,
  onValueChange,
  placeholder = "Select…",
  label,
  disabled,
  className,
}: SelectProps) {
  const reactId = React.useId();
  const isControlled = value !== undefined;
  const [internal, setInternal] = React.useState(defaultValue);
  const current = isControlled ? value : internal;
  const [open, setOpen] = React.useState(false);
  const [active, setActive] = React.useState(0);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);

  const selected = options.find((o) => o.value === current);

  const select = (val: string) => {
    if (!isControlled) setInternal(val);
    onValueChange?.(val);
    setOpen(false);
    triggerRef.current?.focus();
  };

  React.useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      const t = e.target as Node;
      if (triggerRef.current?.contains(t) || listRef.current?.contains(t)) return;
      setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const onKey = (e: React.KeyboardEvent) => {
    if (!open && (e.key === "Enter" || e.key === " " || e.key === "ArrowDown")) {
      e.preventDefault();
      setOpen(true);
      return;
    }
    if (!open) return;
    if (e.key === "Escape") {
      setOpen(false);
      triggerRef.current?.focus();
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      setActive((i) => Math.min(options.length - 1, i + 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActive((i) => Math.max(0, i - 1));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const opt = options[active];
      if (opt && !opt.disabled) select(opt.value);
    }
  };

  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      {label && (
        <label htmlFor={reactId} className="text-xs uppercase tracking-[0.12em] text-[var(--ds-ink-soft)]">
          {label}
        </label>
      )}
      <div className="relative">
        <button
          id={reactId}
          ref={triggerRef}
          type="button"
          disabled={disabled}
          aria-haspopup="listbox"
          aria-expanded={open}
          onClick={() => setOpen((o) => !o)}
          onKeyDown={onKey}
          className={cn(
            "w-full h-10 px-3.5 flex items-center justify-between gap-2 rounded-[var(--ds-field-radius)] border bg-[var(--ds-paper)] border-[var(--ds-line)]",
            "text-[0.95rem] text-left transition-[border-color,box-shadow] duration-150",
            "focus-visible:outline-none focus-visible:border-[var(--ds-ink)] focus-visible:shadow-[0_0_0_4px_color-mix(in_oklab,var(--ds-accent)_25%,transparent)]",
            "disabled:opacity-50 disabled:cursor-not-allowed",
          )}
        >
